    var disqus_loaded = false;

function loadDisqus() {
        if (!disqus_loaded) {
            disqus_loaded = true;
            var dsq = document.createElement('script'); 
            dsq.type = 'text/javascript'; 
            dsq.async = true;
            dsq.setAttribute('data-timestamp', +new Date()); // Obbligatorio per le nuove policy Disqus
